     3	public final class EmailValidator {
     4	
     5	    public static boolean isValid(String email) {
     6	        if (email == null || email.isBlank()) {
     7	            return false;
     8	        }
     9	        int atCount = 0;
    10	        int atIndex = -1;
    11	        for (int i = 0; i < email.length(); i++) {
    12	            if (email.charAt(i) == '@') {
    13	                atCount++;
    14	                atIndex = i;
    15	            }
    16	        }
    17	        if (atCount != 1) {
    18	            return false;
    19	        }
    20	        String localPart = email.substring(0, atIndex);
    21	        String domainPart = email.substring(atIndex + 1);
    22	        if (localPart.isEmpty() || domainPart.isEmpty()) {
    23	            return false;
    24	        }
    25	        if (domainPart.startsWith(".") || domainPart.endsWith(".")) {
    26	            return false;
    27	        }
    28	        int dotIndex = domainPart.indexOf('.');
    29	        return dotIndex > 0;
    30	    }
    31	}
