    11	
    12	    public MessageRules(Map<String, String> environment) {
    13	        this.testMode = "true".equalsIgnoreCase(environment.getOrDefault("HOTEL_TEST_MODE", "false"));
    14	        this.enableArchiveCopy = true;
    15	        this.archiveEmail = "arquivo@pousadamarealta.com.br";
