    23	    public MessageToSend processMessage(String originalTo, String subject, String body) {
    24	        if (!EmailValidator.isValid(originalTo)) {
    25	            return new MessageToSend(originalTo, subject, body, "BLOCKED", null);
    26	        }
    27	
    28	        String recipientEmail = originalTo;
    29	        String processedSubject = subject;
    30	        String processedBody = body;
    31	
    32	        if (testMode) {
    33	            recipientEmail = testEmail;
    34	            processedSubject = "[TESTE] " + subject;
    35	            processedBody = "Destinatário original: " + originalTo + "\n" + body;
